21	import { toast } from 'sonner'
22	import { Checkbox } from '@/components/ui/checkbox'
23	import { Button } from '@/components/ui/button'
24	import {
25	  DropdownMenu,
26	  DropdownMenuContent,
27	  DropdownMenuItem,
28	  DropdownMenuSeparator,
29	  DropdownMenuTrigger,
30	} from '@/components/ui/dropdown-menu'
31	import { Avatar, AvatarFallback } from '@/components/ui/avatar'
32	import { cn } from '@/lib/utils'
33	import type { Urgency } from '@/lib/inbox/urgency'
34	import { URGENCY_META } from '@/lib/inbox/urgency'
35	import type { TeamMember } from './AssignUserPicker'
36	import { AssignUserPicker } from './AssignUserPicker'
37	import type { RichInboxItem } from './InboxClient'
38	import {
39	  archiveInboxItemAction,
40	  resolveInboxItemAction,
41	  assignInboxItemAction,
42	  sendDepositReminderAction,
43	  resendFormLinkAction,
44	  sendWelcomeAction,
45	  sendReviewRequestAction,
46	  sendBirthdayOfferAction,
47	} from '@/app/(app)/inbox/actions'
48	import type { InboxItemKind } from '@/lib/supabase/types'
49	
50	interface InboxItemRowProps {
51	  item: RichInboxItem
52	  urgency: Urgency
53	  isSelected: boolean
54	  isFocused: boolean
55	  members: TeamMember[]
56	  currentUserId: string
57	  onToggleSelect: (id: string) => void
58	  onFocus: (id: string) => void
59	  onRefresh: () => void
60	}
61	
62	// Safely cast item.type to ExtendedInboxItemKind for components that handle
63	// new kinds before they land in the generated InboxItemKind union.
64	function asExtended(kind: InboxItemKind): ExtendedInboxItemKind {
65	  return kind as ExtendedInboxItemKind
66	}
67	
68	// Extended kind type — includes 'review-request' and 'client-birthday' which are
69	// pending Dato migration + db:types regeneration. Remove when types are updated.
70	type ExtendedInboxItemKind = InboxItemKind | 'review-request' | 'client-birthday'
71	
72	function typeIcon(type: ExtendedInboxItemKind) {
73	  switch (type) {
74	    case 'deposit': return <CheckCircle2 className="h-4 w-4 text-stone-brand" aria-hidden="true" />
75	    case 'form': return <FileText className="h-4 w-4 text-stone-brand" aria-hidden="true" />
76	    case 'client': return <UserPlus className="h-4 w-4 text-foreground" aria-hidden="true" />
77	    case 'waitlist': return <Clock className="h-4 w-4 text-stone-brand" aria-hidden="true" />
78	    case 'unread-message': return <MessageCircle className="h-4 w-4 text-foreground" aria-hidden="true" />
79	    case 'review-request': return <Star className="h-4 w-4 text-stone-brand" aria-hidden="true" />
80	    case 'client-birthday': return <Gift className="h-4 w-4 text-stone-brand" aria-hidden="true" />
81	  }
82	}
83	
84	function typeBg(type: ExtendedInboxItemKind): string {
85	  switch (type) {
86	    case 'review-request':
87	    case 'client-birthday':
88	    case 'deposit':
89	    case 'form':
90	    case 'client':
91	    case 'waitlist':
92	    case 'unread-message':
93	      return 'bg-muted'
94	  }
95	}
96	
97	function ctaLabel(type: ExtendedInboxItemKind): string {
98	  switch (type) {
99	    case 'deposit': return 'Send reminder'
100	    case 'form': return 'Resend link'
101	    case 'client': return 'Send welcome'
102	    case 'waitlist': return 'Offer slot'
103	    case 'unread-message': return 'Reply'
104	    case 'review-request': return 'Send request'
105	    case 'client-birthday': return 'Send offer'
106	  }
107	}
108	
109	function ctaIcon(type: ExtendedInboxItemKind) {
110	  switch (type) {
111	    case 'deposit': return <MessageSquare className="h-3 w-3" aria-hidden="true" />
112	    case 'form': return <Mail className="h-3 w-3" aria-hidden="true" />
113	    case 'client': return <Mail className="h-3 w-3" aria-hidden="true" />
114	    case 'waitlist': return <Zap className="h-3 w-3" aria-hidden="true" />
115	    case 'unread-message': return <MessageCircle className="h-3 w-3" aria-hidden="true" />
116	    case 'review-request': return <Star className="h-3 w-3" aria-hidden="true" />
117	    case 'client-birthday': return <Mail className="h-3 w-3" aria-hidden="true" />
118	  }
119	}
120	
121	function initials(name: string): string {
122	  return name
123	    .split(' ')
124	    .map((p) => p[0] ?? '')
125	    .join('')
126	    .toUpperCase()
127	    .slice(0, 2)
128	}
129	
130	export function InboxItemRow({
131	  item,
132	  urgency,
133	  isSelected,
134	  isFocused,
135	  members,
136	  currentUserId,
137	  onToggleSelect,
138	  onFocus,
139	  onRefresh,
140	}: InboxItemRowProps) {
141	  const [isPending, startTransition] = useTransition()
142	  const meta = URGENCY_META[urgency]
143	  const ts = new Date(item.timestamp)
144	  const isRecent = Date.now() - ts.getTime() < 24 * 60 * 60 * 1000
145	
146	  // Extract the raw UUID from composite id like "booking-<uuid>"
147	  const rawId = item.id.replace(/^(booking|consent|waitlist|client|review|birthday)-/, '')
148	  const kind = asExtended(item.type)
149	
150	  const assignedMember = members.find((m) => m.userId === item.assignedTo) ?? null
151	
152	  function handleCta() {
153	    startTransition(async () => {
154	      let result: { ok: boolean; error?: string }
155	
156	      if (kind === 'deposit') {
157	        result = await sendDepositReminderAction(rawId)
158	        if (result.ok) {
159	          toast.success('Deposit reminder sent')
160	          onRefresh()
161	        } else {
162	          toast.error(result.error ?? 'Failed to send reminder')
163	        }
164	        return
165	      }
166	
167	      if (kind === 'form') {
168	        result = await resendFormLinkAction(rawId)
169	        if (result.ok) {
170	          toast.success('Form link resent')
171	          onRefresh()
172	        } else {
173	          toast.error(result.error ?? 'Failed to resend link')
174	        }
175	        return
176	      }
177	
178	      if (kind === 'client') {
179	        result = await sendWelcomeAction(rawId)
180	        if (result.ok) {
181	          toast.success('Welcome email sent')
182	          onRefresh()
183	        } else {
184	          toast.error(result.error ?? 'Failed to send welcome email')
185	        }
186	        return
187	      }
188	
189	      if (kind === 'review-request') {
190	        result = await sendReviewRequestAction(rawId)
191	        if (result.ok) {
192	          toast.success('Review request sent')
193	          onRefresh()
194	        } else {
195	          toast.error(result.error ?? "Couldn't send reminder. Try again or contact support.")
196	        }
197	        return
198	      }
199	
200	      if (kind === 'client-birthday') {
201	        result = await sendBirthdayOfferAction(rawId)
202	        if (result.ok) {
203	          toast.success('Birthday offer sent')
204	          onRefresh()
205	        } else {
206	          toast.error(result.error ?? "Couldn't send reminder. Try again or contact support.")
207	        }
208	        return
209	      }
210	
211	      if (kind === 'waitlist') {
212	        window.location.href = `/bookings/new?waitlist=${rawId}`
213	        return
214	      }
215	
216	      if (kind === 'unread-message') {
217	        window.location.href = item.actionHref
218	      }
219	    })
220	  }
221	
222	  function handleResolve() {
223	    startTransition(async () => {
224	      const result = await resolveInboxItemAction(item.type, rawId)
225	      if (result.ok) {
226	        toast.success('Marked as resolved')
227	        onRefresh()
228	      } else {
229	        toast.error(result.error ?? 'Failed to resolve')
230	      }
231	    })
232	  }
233	
234	  function handleArchive() {
235	    startTransition(async () => {
236	      const result = await archiveInboxItemAction(item.type, rawId)
237	      if (result.ok) {
238	        toast.success('Archived')
239	        onRefresh()
240	      } else {
241	        toast.error(result.error ?? 'Failed to archive')
242	      }
243	    })
244	  }
245	
246	  async function handleAssign(userId: string | null) {
247	    const result = await assignInboxItemAction(item.type, rawId, userId)
248	    if (result.ok) {
249	      toast.success(userId ? 'Assigned' : 'Unassigned')
250	      onRefresh()
251	    } else {
252	      toast.error(result.error ?? 'Failed to assign')
253	    }
254	  }
255	
256	  return (
257	    <div
258	      role="listitem"
259	      data-inbox-item-id={item.id}
260	      data-testid={`inbox-row-${item.type}-${item.id}`}
261	      data-selected={isSelected}
262	      onClick={() => onFocus(item.id)}
263	      onKeyDown={(e) => {
264	        if (e.key === 'Enter' || e.key === ' ') {
265	          e.preventDefault()
266	          onFocus(item.id)
267	        }
268	      }}
269	      tabIndex={0}
270	      className={cn(
271	        'group flex items-center gap-3 bg-card px-4 py-3 transition-colors',
272	        'hover:bg-muted/20 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/30',
273	        isFocused && 'bg-primary/5 ring-1 ring-inset ring-primary/20',
274	        isSelected && 'bg-primary/5',
275	        isPending && 'opacity-60',
276	        'last:rounded-b-lg',
277	      )}
278	    >
279	      {/* Checkbox */}
280	      <Checkbox
281	        checked={isSelected}
282	        onCheckedChange={() => onToggleSelect(item.id)}
283	        onClick={(e) => e.stopPropagation()}
284	        aria-label={`Select ${item.title}`}
285	        className="shrink-0"
286	      />
287	
288	      {/* Urgency dot */}
289	      <span
290	        className={cn('h-1.5 w-1.5 shrink-0 rounded-full', meta.dotClass)}
291	        aria-hidden="true"
292	      />
293	
294	      {/* Type icon */}
295	      <div className={cn('flex h-8 w-8 shrink-0 items-center justify-center rounded-full', typeBg(kind))}>
296	        {typeIcon(kind)}
297	      </div>
298	
299	      {/* Content */}
300	      <div className="min-w-0 flex-1">
301	        <p className="truncate text-[13px] font-medium text-foreground leading-tight">
302	          {item.title}
303	        </p>
304	        <p className="truncate text-[12px] text-muted-foreground">{item.subtitle}</p>
305	      </div>
306	
307	      {/* Assignee avatar */}
308	      {assignedMember && (
309	        <Avatar className="h-6 w-6 shrink-0" aria-label={`Assigned to ${assignedMember.name}`}>
310	          <AvatarFallback className="text-[9px] bg-muted">
311	            {initials(assignedMember.name)}
312	          </AvatarFallback>
313	        </Avatar>
314	      )}
315	
316	      {/* Timestamp */}
317	      <time
318	        dateTime={item.timestamp}
319	        className="shrink-0 text-[11px] text-muted-foreground/60 hidden sm:block"
320	        title={format(ts, 'PPpp')}
321	      >
322	        {isRecent ? formatDistanceToNow(ts, { addSuffix: true }) : format(ts, 'MMM d')}
323	      </time>
324	
325	      {/* One-click CTA */}
326	      <Button
327	        variant="outline"
328	        size="sm"
329	        onClick={(e) => { e.stopPropagation(); handleCta() }}
330	        disabled={isPending}
331	        className="shrink-0 h-7 gap-1.5 text-[11px] hidden sm:flex"
332	        aria-label={`${ctaLabel(kind)} for ${item.title}`}
333	      >
334	        {ctaIcon(kind)}
335	        <span className="hidden md:inline">{ctaLabel(kind)}</span>
336	      </Button>
337	
338	      {/* Mobile: icon-only CTA */}
339	      <Button
340	        variant="outline"
341	        size="sm"
342	        onClick={(e) => { e.stopPropagation(); handleCta() }}
343	        disabled={isPending}
344	        className="shrink-0 h-7 w-7 p-0 sm:hidden"
345	        aria-label={ctaLabel(kind)}
346	      >
347	        {ctaIcon(kind)}
348	      </Button>
349	
350	      {/* Kebab menu */}
351	      <DropdownMenu>
352	        <DropdownMenuTrigger
353	          render={
354	            <Button
355	              variant="ghost"
356	              size="sm"
357	              onClick={(e) => e.stopPropagation()}
358	              className="h-7 w-7 shrink-0 p-0 text-muted-foreground/60 opacity-0 group-hover:opacity-100 group-focus-within:opacity-100 focus-visible:opacity-100"
359	              aria-label="More options"
360	            >
361	              <MoreHorizontal className="h-4 w-4" aria-hidden="true" />
362	            </Button>
363	          }
364	        />
365	        <DropdownMenuContent align="end" side="bottom">
366	          <DropdownMenuItem
367	            onClick={(e) => { e.stopPropagation(); handleResolve() }}
368	            className="gap-2 text-xs"
369	          >
370	            <UserCheck className="h-3.5 w-3.5" aria-hidden="true" />
371	            Mark resolved
372	          </DropdownMenuItem>
373	          <DropdownMenuItem
374	            onClick={(e) => { e.stopPropagation(); handleArchive() }}
375	            className="gap-2 text-xs"
376	          >
377	            <Archive className="h-3.5 w-3.5" aria-hidden="true" />
378	            Archive
379	          </DropdownMenuItem>
380	          <DropdownMenuSeparator />
381	          {/* View link */}
382	          <DropdownMenuItem
383	            className="gap-2 text-xs"
384	            render={<Link href={item.actionHref} onClick={(e) => e.stopPropagation()} />}
385	          >
386	            View details
387	          </DropdownMenuItem>
388	        </DropdownMenuContent>
389	      </DropdownMenu>
390	
391	      {/* Assign picker — hidden on mobile */}
392	      <div className="hidden sm:block" onClick={(e) => e.stopPropagation()}>
393	        <AssignUserPicker
394	          members={members}
395	          currentUserId={currentUserId}
396	          currentAssignee={item.assignedTo}
397	          onAssign={handleAssign}
398	          compact
399	        />
400	      </div>
401	    </div>
402	  )
403	}
