// Extend the generated InboxItemKind with kinds pending Dato migration + db:types regen.
// Remove each entry here once pnpm db:types picks up the enum value.
export type InboxItemType =
  | InboxItemKind
  | 'review-request'
  | 'client-birthday'
  | 'guest-residency-ending'

// InboxItemType is imported from InboxClient which extends InboxItemKind with
// kinds pending Dato migration. urgency.ts uses it to avoid a separate re-export.
import type { InboxItemType } from '@/components/inbox/InboxClient'

export type Urgency = 'now' | 'today' | 'this_week' | 'later'

