// ─── Types ────────────────────────────────────────────────────

type ActionResult<T = undefined> =
  | { ok: true; data?: T; error?: never }
  | { ok: false; error: string; data?: never }

interface BatchItem {
  kind: InboxItemType
  id: string
}

/** Subset of InboxItemKind that inbox_assignments supports (excludes transient/extended kinds) */
type DBInboxItemKind = 'deposit' | 'form' | 'waitlist' | 'client'

function isDBInboxKind(kind: InboxItemType): kind is DBInboxItemKind {
  return kind === 'deposit' || kind === 'form' || kind === 'waitlist' || kind === 'client'
}

